public final class com.example.tools.ProjectTools implements org.machanism.machai.ai.tools.FunctionTools {
  @org.machanism.machai.ai.tools.Tool(name = "project_summary", description = "Creates a project summary.")
  public java.lang.String summarize(@org.machanism.machai.ai.tools.Param(name = "text", description = "Text to summarize") java.lang.String text) {
    return text == null ? "" : text.substring(0, java.lang.Math.min(text.length(), 120));
  }
}

